			type == vnodeTypeNames.selectTag &&
			normalizedProps.multiple &&
			Array.isArray(normalizedProps.value)
		) {
			// forEach() always returns undefined, which we abuse here to unset the value prop.
			normalizedProps.value = toChildArray(props.children).forEach(child => {
				child.props.selected =
					normalizedProps.value.indexOf(child.props.value) != -1;
			});
		}

		// Adding support for defaultValue in select tag
		if (
			type == vnodeTypeNames.selectTag &&
			normalizedProps.defaultValue != null
		) {
			normalizedProps.value = toChildArray(props.children).forEach(child => {
				if (normalizedProps.multiple) {
					child.props.selected =
						normalizedProps.defaultValue.indexOf(child.props.value) != -1;
				} else {
					child.props.selected =
						normalizedProps.defaultValue == child.props.value;
				}
			});
		}

		vnode.props = normalizedProps;

		if (props.class != props.className) {
			propAliasRules.classNameDescriptor.enumerable = 'className' in props;
			if (props.className != null) normalizedProps.class = props.className;
			Object.defineProperty(
				normalizedProps,
				'className',
				propAliasRules.classNameDescriptor
			);
		}
	}

	vnode.$$typeof = this.elementType;
};

const compatVNodeBridge = new CompatVNodeBridge(REACT_ELEMENT_TYPE, IS_DOM);

let oldVNodeHook = options.vnode;
options.vnode = vnode => {
	compatVNodeBridge.normalizeVNode(vnode);
	if (oldVNodeHook) oldVNodeHook(vnode);
};

// Only needed for react-relay
let currentComponent;
const oldBeforeRender = options._render;
options._render = function(vnode) {
	if (oldBeforeRender) {
		oldBeforeRender(vnode);
	}
	currentComponent = vnode._component;

